  pass: passou,
  score: passou ? 1 : 0,
  reason: JSON.stringify({
    deveUsar,
    ferramentasEsperadas: esperadas,
    ferramentasExecutadas: executadas,
    resultado: passou ? "PASS" : "FAIL"
  })
};

